"use client";
import { lyricStatus } from "@/lib/lyrics/timing";
import LyricTimingEditor from "@/components/admin/lyrics/LyricTimingEditor";
import { getDeletedReleaseSnapshot } from "@/lib/releases/deletion-store";
import DeleteReleaseButton from "@/components/admin/DeleteReleaseButton";
import CreditsEditor from "@/components/admin/CreditsEditor";
import { editableCreditGroups } from "@/lib/credits/contract";


import { useState, useEffect, useRef, useCallback, useId, cloneElement, isValidElement } from "react";
import { useAuth } from "@/context/AuthContext";
import { catalogCoverUrl, catalogMotionVideoUrl } from "@/lib/media-urls";
import { UploadWizard } from "@/components/admin/UploadWizard";
import { uploadAssetToR2 } from "@/lib/media/r2-upload-client";
import {
  beginMasterReplacement,
  stageMasterReplacement,
} from "@/lib/media/master-revision-client";
import { VIDEO_COVER_ACCEPT, MASTER_AUDIO_ACCEPT } from "@/lib/media/admin-upload-contract";
import { signalCatalogMutation } from "@/lib/storefront/catalog-refresh-store";
import { AdminVerificationOverlay } from "@/components/admin/AdminVerificationOverlay";
import { RECOVERABLE_ADMIN_AUTH_CODES } from "@/lib/auth/admin-authority-diagnostics";

// ── Design tokens ────────────────────────────────────────────────────────────────
const C = {
  bg:           "#050505",
  surface:      "#0d0d0d",
  surface2:     "#111",
  surface3:     "#161616",
  border:       "rgba(255,255,255,0.06)",
  border2:      "rgba(255,255,255,0.12)",
  accent:       "#00ffff",
  accentDim:    "rgba(0,255,255,0.07)",
  accentBorder: "rgba(0,255,255,0.22)",
  purple:       "#a259ff",
  text:         "#e8e8e8",
  muted:        "rgba(255,255,255,0.45)",
  muted2:       "rgba(255,255,255,0.28)",
  muted3:       "rgba(255,255,255,0.14)",
  success:      "#32d74b",
  warn:         "#ff9f0a",
  error:        "#ff453a",
};

const STATUS_COLORS = {
  published: C.success,
  scheduled: C.warn,
  draft:     C.muted2,
  failed:    C.error,
};

const TYPE_LABELS = {
  single:  "Single",
  feature: "Feature",
  album:   "Album",
  ep:      "EP",
  mixtape: "Mixtape",
  unclassified: "Needs classification",
};

const SLUG_PREFIXES = {
  single:  "/song/",
  feature: "/feature/",
  album:   "/album/",
  ep:      "/album/",
  mixtape: "/album/",
};

// ── Shared atoms ─────────────────────────────────────────────────────────────────
function Label({ children }) {
  return (
    <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.1em", color: C.muted2, textTransform: "uppercase", marginBottom: 7 }}>
      {children}
    </div>
  );
}

function Field({ label, children, hint }) {
  const fieldId = useId();
  return (
    <div style={{ marginBottom: 18 }}>
      {label && <Label><label htmlFor={fieldId}>{label}</label></Label>}
      {isValidElement(children) ? cloneElement(children, { id: fieldId }) : children}
      {hint && <div style={{ fontSize: 11, color: C.muted2, marginTop: 5 }}>{hint}</div>}
    </div>
  );
}

function Inp({ id, value, onChange, placeholder, type = "text" }) {
  return (
    <input
      id={id}
      type={type}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      style={{
        width: "100%", background: C.surface2, border: `1px solid ${C.border2}`,
        borderRadius: 8, color: C.text, fontSize: 14, padding: "10px 13px",
        outline: "none", boxSizing: "border-box", fontFamily: "inherit",
      }}
    />
  );
}

function Sel({ id, value, onChange, children }) {
  return (
    <select
      id={id}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      style={{
        width: "100%", background: C.surface2, border: `1px solid ${C.border2}`,
        borderRadius: 8, color: C.text, fontSize: 14, padding: "10px 13px",
        outline: "none", boxSizing: "border-box", fontFamily: "inherit",
      }}
    >
      {children}
    </select>
  );
}

function Btn({ onClick, children, variant = "primary", disabled = false, small = false }) {
  const styles = {
    primary:     { background: C.accent,      color: "#000", border: "none" },
    secondary:   { background: C.surface2,    color: C.text, border: `1px solid ${C.border2}` },
    danger:      { background: C.error,       color: "#fff", border: "none" },
    warn:        { background: C.warn,        color: "#000", border: "none" },
    ghost:       { background: "none",        color: C.muted, border: `1px solid ${C.border}` },
    accentGhost: { background: C.accentDim,   color: C.accent, border: `1px solid ${C.accentBorder}` },
  };
  return (
    <button
      onClick={disabled ? undefined : onClick}
      style={{
        borderRadius: 8, padding: small ? "7px 14px" : "11px 22px",
        fontSize: small ? 11 : 13, fontWeight: 800, letterSpacing: "0.06em",
        textTransform: "uppercase", cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.5 : 1, fontFamily: "inherit", transition: "opacity 0.15s",
        ...styles[variant],
      }}
    >
      {children}
    </button>
  );
}

function StatusBadge({ status }) {
  return (
    <span style={{
      fontSize: 10, fontWeight: 700, letterSpacing: "0.08em",
      color: STATUS_COLORS[status] || C.muted2,
      background: `${STATUS_COLORS[status] || C.muted2}18`,
      borderRadius: 5, padding: "3px 8px",
    }}>
      {status?.toUpperCase()}
    </span>
  );
}

function SaveMsg({ msg }) {
  if (!msg) return null;
  const isErr = msg.startsWith("Error") || msg.startsWith("Failed");
  return (
    <div role={isErr ? "alert" : "status"} style={{
      background: isErr ? "rgba(255,69,58,0.08)" : "rgba(50,215,75,0.08)",
      border: `1px solid ${isErr ? "rgba(255,69,58,0.3)" : "rgba(50,215,75,0.3)"}`,
      borderRadius: 8, padding: "10px 16px", marginBottom: 16, fontSize: 13,
      color: isErr ? C.error : C.success,
    }}>
      {msg}
    </div>
  );
}

function ProgressBar({ pct }) {
  return (
    <div style={{ background: C.surface, borderRadius: 4, height: 5, overflow: "hidden", marginTop: 8 }}>
      <div style={{ background: C.accent, width: `${pct}%`, height: "100%", transition: "width 0.2s" }} />
    </div>
  );
}

// ── Price options ─────────────────────────────────────────────────────────────────
const PRICE_OPTIONS = {
  single:  ["2.99", "5.99", "7.99", "14.99", "19.99"],
  feature: ["2.99", "5.99", "7.99", "14.99", "19.99"],
  album:   ["12.99", "15.99", "19.99", "29.99", "49.99", "79.99"],
  ep:      ["9.99", "15.99", "19.99", "49.99", "79.99"],
  mixtape: ["9.99", "15.99", "19.99", "49.99", "79.99"],
};

function PriceSelector({ releaseType, value, onChange }) {
  const options = PRICE_OPTIONS[releaseType] || PRICE_OPTIONS.single;
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
      {options.map((opt) => (
        <button
          key={opt}
          type="button"
          onClick={() => onChange(opt)}
          style={{
            background: value === opt ? C.accentDim : C.surface2,
            border: `2px solid ${value === opt ? C.accent : C.border2}`,
            borderRadius: 8, padding: "9px 16px", cursor: "pointer",
            fontSize: 13, fontWeight: 700, color: value === opt ? C.accent : C.text,
            fontFamily: "inherit",
          }}
        >
          ${opt}
        </button>
      ))}
    </div>
  );
}

// ── Home Landing ─────────────────────────────────────────────────────────────────
function HomeLanding({ releaseCount, onUpload, onMyReleases }) {
  return (
    <div style={{ padding: "36px 0 80px", fontFamily: "-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif" }}>
      <div style={{ marginBottom: 36 }}>
        <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.14em", color: C.accent, textTransform: "uppercase", marginBottom: 8 }}>Admin</div>
        <h1 style={{ fontSize: 28, fontWeight: 900, color: C.text, margin: 0, lineHeight: 1.1 }}>Manage Releases</h1>
        <p style={{ color: C.muted, fontSize: 13, marginTop: 8 }}>Upload new music or manage your existing catalog.</p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 16, maxWidth: 680 }}>

        {/* Upload New Release */}
        <button
          onClick={onUpload}
          style={{
            background: "linear-gradient(135deg, rgba(0,255,255,0.10) 0%, rgba(0,255,255,0.03) 100%)",
            border: `1px solid ${C.accentBorder}`,
            borderRadius: 16, padding: "28px 24px", cursor: "pointer", textAlign: "left",
            fontFamily: "inherit",
          }}
          onMouseEnter={(e) => { e.currentTarget.style.borderColor = C.accent; e.currentTarget.style.background = "rgba(0,255,255,0.14)"; }}
          onMouseLeave={(e) => { e.currentTarget.style.borderColor = C.accentBorder; e.currentTarget.style.background = "linear-gradient(135deg, rgba(0,255,255,0.10) 0%, rgba(0,255,255,0.03) 100%)"; }}
        >
          <div style={{ fontSize: 30, marginBottom: 12 }}>＋</div>
          <div style={{ fontSize: 16, fontWeight: 800, color: C.accent, marginBottom: 6 }}>Upload New Release</div>
          <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.6 }}>
            Single, Feature, Album, EP, or Mixtape — master audio, artwork, lyrics, credits.
          </div>
        </button>

        {/* My Releases */}
        <button
          onClick={onMyReleases}
          style={{
            background: C.surface,
            border: `1px solid ${C.border}`,
            borderRadius: 16, padding: "28px 24px", cursor: "pointer", textAlign: "left",
            fontFamily: "inherit",
          }}
          onMouseEnter={(e) => { e.currentTarget.style.borderColor = C.border2; e.currentTarget.style.background = C.surface2; }}
          onMouseLeave={(e) => { e.currentTarget.style.borderColor = C.border; e.currentTarget.style.background = C.surface; }}
        >
          <div style={{ fontSize: 30, marginBottom: 12 }}>📂</div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
            <span style={{ fontSize: 16, fontWeight: 800, color: C.text }}>My Releases</span>
            {releaseCount > 0 && (
              <span style={{ fontSize: 11, fontWeight: 700, color: C.muted2, background: C.surface2, border: `1px solid ${C.border}`, borderRadius: 5, padding: "2px 8px" }}>
                {releaseCount}
              </span>
            )}
          </div>
          <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.6 }}>
            View all releases. Update cover art, audio, lyrics, metadata. Propagates to every page instantly.
          </div>
        </button>
      </div>
    </div>
  );
}

// ── Release List View ────────────────────────────────────────────────────────────
const RELEASE_TYPE_FILTERS = [
  ["all", "All Releases"], ["single", "Singles"], ["feature", "Features"],
  ["album", "Albums"], ["ep", "EPs"], ["mixtape", "Mixtapes"],
];

function managementReleaseType(release) {
  const type = String(release.release_category || release.release_type || "").trim().toLowerCase();
  if (["single", "singles"].includes(type)) return "single";
  if (["feature", "features"].includes(type)) return "feature";
  if (["album", "albums"].includes(type)) return "album";
  if (type === "ep" || type === "mixtape") return type;
  return null;
}

function ReleaseListView({ onDeleted, deletionNotice, releases, loading, error, filter, onFilter, typeFilter, onTypeFilter, onRefresh, onEdit, onNew, onBack, lastResult }) {
  const counts = {
    all:       releases.length,
    published: releases.filter((r) => r.status === "published").length,
    scheduled: releases.filter((r) => r.status === "scheduled").length,
    draft:     releases.filter((r) => r.status === "draft").length,
  };

  const filtered = filter === "all"
    ? releases
    : releases.filter((r) => r.status === filter);
  const visibleReleases = typeFilter === "all"
    ? filtered
    : filtered.filter((release) => managementReleaseType(release) === typeFilter);
  const typeCounts = Object.fromEntries(RELEASE_TYPE_FILTERS.map(([type]) => [
    type,
    type === "all" ? filtered.length : filtered.filter((release) => managementReleaseType(release) === type).length,
  ]));

  return (
    <div style={{ padding: "28px 0 80px", fontFamily: "-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif" }}>

      {/* Header */}
      <div style={{ marginBottom: 22 }}>
        <button onClick={onBack} style={backBtnStyle}>← Manage Releases</button>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 16, flexWrap: "wrap", marginTop: 10 }}>
          <h1 style={{ fontSize: 22, fontWeight: 900, color: C.text, margin: 0 }}>My Releases</h1>
          <Btn onClick={onNew} small>+ Upload New</Btn>
        </div>
      </div>

      {/* Last publish success */}
      {lastResult && (
        <div style={{ background: "rgba(50,215,75,0.08)", border: "1px solid rgba(50,215,75,0.3)", borderRadius: 10, padding: "12px 16px", marginBottom: 16, display: "flex", alignItems: "center", gap: 10 }}>
          <span>🎉</span>
          <div>
            <span style={{ fontSize: 13, fontWeight: 700, color: C.success }}>
              {lastResult.status === "scheduled" ? "Release Scheduled!" : "Release is Live!"}
            </span>
            {lastResult.slug && (
              <span style={{ fontSize: 12, color: C.muted, marginLeft: 10 }}>{lastResult.slug}</span>
            )}
          </div>
        </div>
      )}

      {deletionNotice && <div role="status" style={{ color: C.success, marginBottom: 16 }}>{deletionNotice}</div>}

      {/* Filter tabs */}
      <div style={{ display: "flex", gap: 6, marginBottom: 18, flexWrap: "wrap" }}>
        {["all", "published", "scheduled", "draft"].map((f) => (
          <button
            key={f}
            onClick={() => onFilter(f)}
            style={{
              background: filter === f ? C.accentDim : C.surface2,
              border: `1px solid ${filter === f ? C.accentBorder : C.border}`,
              borderRadius: 7, padding: "7px 13px", fontSize: 11, fontWeight: 700,
              color: filter === f ? C.accent : C.muted, cursor: "pointer",
              textTransform: "capitalize", letterSpacing: "0.05em", fontFamily: "inherit",
            }}
          >
            {f.charAt(0).toUpperCase() + f.slice(1)} ({counts[f]})
          </button>
        ))}
        <button
          onClick={onRefresh}
          style={{ marginLeft: "auto", background: "none", border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 12px", fontSize: 11, color: C.muted2, cursor: "pointer", fontFamily: "inherit" }}
        >
          ↻
        </button>
      </div>

      <div role="tablist" aria-label="Filter releases by type" style={{ display: "flex", gap: 6, margin: "-8px 0 18px", flexWrap: "wrap" }}>
        {RELEASE_TYPE_FILTERS.map(([type, label]) => (
          <button
            key={type}
            type="button"
            role="tab"
            aria-selected={typeFilter === type}
            onClick={() => onTypeFilter(type)}
            style={{
              background: typeFilter === type ? C.accentDim : C.surface2,
              border: `1px solid ${typeFilter === type ? C.accentBorder : C.border}`,
              borderRadius: 7, padding: "7px 12px", fontSize: 11, fontWeight: 700,
              color: typeFilter === type ? C.accent : C.muted, cursor: "pointer", fontFamily: "inherit",
            }}
          >
            {label} ({typeCounts[type]})
          </button>
        ))}
      </div>
      <div style={{ color: C.muted2, fontSize: 11, margin: "-10px 0 16px" }}>
        Releases without an explicit type classification remain available in All Releases.
      </div>

      {error && (
        <div style={{ background: "rgba(255,69,58,0.08)", border: "1px solid rgba(255,69,58,0.3)", borderRadius: 8, padding: "12px 16px", marginBottom: 16, fontSize: 13, color: C.error }}>
          {error}
        </div>
      )}

      {loading ? (
        <div style={{ textAlign: "center", padding: "60px 0", color: C.muted }}>Loading releases…</div>
      ) : visibleReleases.length === 0 ? (
        <div style={{ textAlign: "center", padding: "60px 0" }}>
          <div style={{ fontSize: 13, color: C.muted, marginBottom: 16 }}>No releases found.</div>
          {filter === "all" && typeFilter === "all" && <Btn onClick={onNew}>Upload Your First Release</Btn>}
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {visibleReleases.map((rel) => {
            const coverSrc = rel.cover_art_r2_key ? catalogCoverUrl(rel.cover_art_r2_key) : null;
            const prefix   = SLUG_PREFIXES[rel.release_type] || "/song/";
            const isLive   = rel.status === "published" && rel.storefront_visible;
            const dateStr  = rel.release_date
              ? new Date(rel.release_date + "T00:00:00").toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" })
              : rel.created_at
                ? new Date(rel.created_at).toLocaleDateString("en-US", { year: "numeric", month: "short" })
                : "—";

            return (
              <div
                key={rel.id}
                role="button"
                tabIndex={0}
                aria-label={`Open ${rel.title || "untitled release"}`}
                onClick={() => onEdit(rel)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onEdit(rel); }
                }}
                style={{
                  background: C.surface, border: `1px solid ${C.border}`,
                  borderRadius: 12, padding: "14px 18px", cursor: "pointer",
                  display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap",
                }}
              >
                {/* Cover thumbnail */}
                <div style={{
                  width: 56, height: 56, borderRadius: 8, flexShrink: 0,
                  background: C.surface2, overflow: "hidden",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  border: `1px solid ${C.border}`,
                }}>
                  {coverSrc
                    ? <img src={coverSrc} alt={rel.title || rel.slug} loading="lazy" decoding="async" onError={(event) => { event.currentTarget.remove(); }} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                    : <span style={{ fontSize: 20 }}>🎵</span>
                  }
                </div>

                {/* Info */}
                <div style={{ flex: 1, minWidth: 140 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 3 }}>
                    <div style={{ fontSize: 14, fontWeight: 700, color: C.text }}>
                      {rel.title || <span style={{ color: C.muted2, fontStyle: "italic" }}>Untitled</span>}
                    </div>
                    <StatusBadge status={rel.status} />
                  </div>
                  <div style={{ fontSize: 11, color: C.muted2 }}>
                    {TYPE_LABELS[rel.release_type] || rel.release_type} · {dateStr}
                  </div>
                  <div style={{ fontSize: 10, color: C.muted3, marginTop: 2 }}>
                    {rel.track_counts?.ready ?? "?"}/{rel.track_counts?.total ?? "?"} tracks ready
                  </div>
                </div>

                {/* Actions */}
                <div style={{ display: "flex", gap: 8, flexShrink: 0, flexWrap: "wrap" }}>
                  <DeleteReleaseButton release={rel} onDeleted={onDeleted} />
                  {isLive && rel.slug && (
                    <a
                      href={prefix + rel.slug}
                      target="_blank"
                      rel="noopener noreferrer"
                      onClick={(e) => e.stopPropagation()}
                      style={{
                        background: C.accentDim, border: `1px solid ${C.accentBorder}`,
                        borderRadius: 7, padding: "6px 12px", fontSize: 11, color: C.accent,
                        textDecoration: "none", fontWeight: 700, fontFamily: "inherit",
                      }}
                    >
                      View ↗
                    </a>
                  )}
                  <button
                    onClick={(e) => { e.stopPropagation(); onEdit(rel); }}
                    style={{
                      background: C.surface2, border: `1px solid ${C.border2}`, borderRadius: 7,
                      padding: "6px 14px", fontSize: 11, color: C.muted, cursor: "pointer",
                      fontFamily: "inherit", fontWeight: 700,
                    }}
                  >
                    Edit
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ── Release Editor Panel ─────────────────────────────────────────────────────────
export function ReleaseEditorPanel({ release: relStub, onBack, onSaved }) {
  const { currentUser } = useAuth();
  const [detail,     setDetail]     = useState(null);
  const [loading,    setLoading]    = useState(true);
  const [loadError,  setLoadError]  = useState(null);
  const [section,    setSection]    = useState("metadata");
  const [saving,     setSaving]     = useState(false);
  const [saveMsg,    setSaveMsg]    = useState(null);
  const [removeCandidate, setRemoveCandidate] = useState(null);
  const [removingTrackId, setRemovingTrackId] = useState(null);
  const [removeTrackError, setRemoveTrackError] = useState("");
  const [swipedTrackId, setSwipedTrackId] = useState(null);
  const trackTouchStartRef = useRef(null);

  // Metadata form state
  const [editTitle,  setEditTitle]  = useState("");
  const [editPrice,  setEditPrice]  = useState("");
  const [editGenre,  setEditGenre]  = useState("");
  const [editDate,   setEditDate]   = useState("");
  const [creditGroups, setCreditGroups] = useState(null);
  const [recordings, setRecordings] = useState([]);
  const [editUpc, setEditUpc] = useState("");
  const [editArtist, setEditArtist] = useState("");
  const [editType, setEditType] = useState("");
  const [editLifecycle, setEditLifecycle] = useState({});

  // Lyrics (keyed by track id)
  const [trackLyrics, setTrackLyrics] = useState({});
  const [lyricRecordingId, setLyricRecordingId] = useState(null);

  // Static cover upload state — seeded "done" when the release already has a
  // cover, so reopening never implies a re-upload is required.
  const [coverState,   setCoverState]   = useState({ status: relStub.cover_art_r2_key ? "done" : "idle", error: null, pct: 0 });
  const [coverPreview, setCoverPreview] = useState(null);
  const coverPreviewObjectUrlRef = useRef(null);

  // Animated cover video upload state — same persistence rule as cover art.
  const [mp4State,   setMp4State]   = useState({ status: relStub.metadata?.animated_cover_r2_key ? "done" : "idle", error: null, pct: 0 });
  const [mp4Preview, setMp4Preview] = useState(null);
  const mp4PreviewObjectUrlRef = useRef(null);

  // Audio replace state
  const [audioReplacing,  setAudioReplacing]  = useState(null);
  const [audioPhase,      setAudioPhase]      = useState("idle"); // idle | uploading | processing | done | error
  const [audioProgress,   setAudioProgress]   = useState(0);
  const [audioNewKey,     setAudioNewKey]     = useState(null);
  const [audioError,      setAudioError]      = useState("");
  const [audioReauthRequired, setAudioReauthRequired] = useState(false);
  const audioXhrRef = useRef(null);
  const audioOperationRef = useRef(null);
  const audioResumeRef = useRef(null);

  useEffect(() => () => {
    audioXhrRef.current?.abort?.();
    for (const ref of [coverPreviewObjectUrlRef, mp4PreviewObjectUrlRef]) {
      if (ref.current) URL.revokeObjectURL(ref.current);
      ref.current = null;
    }
  }, []);

  const GENRES = ["R&B","Hip-Hop","Pop","Alternative R&B","Soul","Neo-Soul","Trap","Rap","Melodic Rap","Pop/R&B","Hiphop/R&B","Electronic","Other"];

  // ── Load release detail ────────────────────────────────────────────────────────
  useEffect(() => {
    if (!relStub?.id) return;
    setLoading(true);
    setLoadError(null);
    let cancelled = false;
    const controller = new AbortController();
    fetch(`/api/admin/releases/${relStub.id}`, { signal: controller.signal, cache: "no-store" })
      .then((r) => r.json())
      .then((d) => {
        if (d.error) throw new Error(d.error);
        if (cancelled) return;
        setDetail(d);
        setCreditGroups(d.release.credit_groups || editableCreditGroups(d.release));
        setRecordings(d.tracks || []);
        setEditUpc(d.release.upc || "");
        setEditArtist(typeof d.release.artist === "string" ? d.release.artist : d.release.artist?.name || "");
        setEditType(d.release.release_type || "");
        setEditLifecycle(Object.fromEntries(["scheduled_at", "available_at", "release_timezone", "upcoming_visible", "preview_before_release", "preorder_enabled", "preorder_starts_at", "preorder_price_cents", "early_access_enabled", "early_access_starts_at", "unavailable_at"].map(k => [k, d.release[k]])));
        setEditTitle(d.product?.title  || "");
        setEditPrice(Number.isFinite(d.product?.price_cents) ? (d.product.price_cents / 100).toFixed(2) : "");
        setEditGenre(d.product?.genre  || "");
        setEditDate(d.release?.release_date || "");
        const lMap = {};
        for (const t of (d.lyric_recordings || d.tracks || [])) lMap[t.id] = t.lyrics || "";
        setTrackLyrics(lMap);
        // The detail response is authoritative; the list stub may predate
        // canonical artwork metadata resolution.
        const coverKey = d.release?.cover_art_r2_key || relStub.cover_art_r2_key;
        if (coverKey) setCoverPreview(catalogCoverUrl(coverKey));
        // Seed animated-cover preview from persisted server data so the "already
        // uploaded" state (and its video player) survives a reopen.
        const animatedKey = d.release?.animated_cover_r2_key;
        if (animatedKey) setMp4Preview(catalogMotionVideoUrl(animatedKey));
      })
      .catch((err) => { if (!cancelled && err.name !== "AbortError") setLoadError(err.message); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; controller.abort(); };
  }, [relStub?.id, relStub?.cover_art_r2_key]);

  const showMsg = useCallback((msg) => {
    setSaveMsg(msg);
    setTimeout(() => setSaveMsg(null), 3500);
  }, []);

  // ── Metadata save ─────────────────────────────────────────────────────────────
  const saveMetadata = async () => {
    setSaving(true);
    try {
      const patch = { revision: detail.revision };
      const baselineArtist = typeof detail.release.artist === "string" ? detail.release.artist : detail.release.artist?.name || "";
      const fields = { title: [editTitle, detail.product.title], price: [editPrice, Number.isFinite(detail.product.price_cents) ? (detail.product.price_cents / 100).toFixed(2) : ""], genre: [editGenre, detail.product.genre || ""], release_date: [editDate, detail.release.release_date || ""], upc: [editUpc, detail.release.upc || ""], artist: [editArtist, baselineArtist], release_type: [editType, detail.release.release_type] };
      for (const [key, [next, previous]] of Object.entries(fields)) if (next !== previous) patch[key] = next;
      for (const [key, value] of Object.entries(editLifecycle)) if (value !== detail.release[key]) patch[key] = value;
      const res  = await fetch(`/api/admin/releases/${detail.release.id}`, {
        method:  "PATCH",
        headers: { "Content-Type": "application/json" },
        body:    JSON.stringify(patch),
      });
      const json = await res.json();
      if (!res.ok || json.ok === false) throw new Error(json.error || json.errors?.[0] || "Save failed");
      signalCatalogMutation("release_metadata_updated");
      setDetail(previous => ({ ...previous, revision: json.revision || previous.revision,
        product: { ...previous.product, title: editTitle, genre: editGenre, price_cents: editPrice === "" ? previous.product.price_cents : Math.round(Number(editPrice) * 100) },
        release: { ...previous.release, upc: editUpc, artist: editArtist, release_type: editType, release_date: editDate, ...editLifecycle },
      }));
      showMsg("Metadata saved");
      onSaved();
    } catch (err) {
      showMsg("Error: " + err.message);
    } finally {
      setSaving(false);
    }
  };

  const saveCredits = async () => {
    setSaving(true);
    try {
      const response = await fetch(`/api/admin/releases/${detail.release.id}`, {
        method: "PATCH", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ revision: detail.revision, credit_groups: creditGroups, upc: editUpc,
          recordings: recordings.map(t => ({ id: t.id, title: t.title, credit_groups: t.credit_groups, isrc: t.isrc, inherit_credits: t.inherit_credits })) }),
      });
      const body = await response.json();
      if (!response.ok || !body.ok) throw new Error(body.error || "Credits could not be saved");
      signalCatalogMutation("release_credits_updated");
      setDetail(previous => ({ ...previous, revision: body.revision || previous.revision,
        release: { ...previous.release, credit_groups: creditGroups, upc: editUpc }, tracks: recordings,
      }));
      showMsg("Credits and identifiers saved"); onSaved();
    } catch (error) { showMsg("Error: " + error.message); }
    finally { setSaving(false); }
  };

  // ── Lyrics save ───────────────────────────────────────────────────────────────
  const saveLyrics = async () => {
    setSaving(true);
    try {
      const track_lyrics = Object.entries(trackLyrics).map(([id, lyrics]) => ({ id, lyrics }));
      const res  = await fetch(`/api/admin/releases/${detail.release.id}`, {
        method:  "PATCH",
        headers: { "Content-Type": "application/json" },
        body:    JSON.stringify({ lyric_edit_version: 1, revision: detail.revision, track_lyrics }),
      });
      const json = await res.json();
      if (!res.ok || json.ok === false) throw new Error(json.error || json.errors?.[0] || "Save failed");
      setDetail(previous => ({ ...previous, revision: json.revision || previous.revision }));
      signalCatalogMutation("release_lyrics_updated");
      showMsg("Lyrics saved");
    } catch (err) {
      showMsg("Error: " + err.message);
    } finally {
      setSaving(false);
    }
  };

  // ── Unified cover upload (still image or cover video) ─────────────────────────
  // presigned → XHR PUT with progress → complete → revalidation fires server-side
  const uploadAsset = useCallback(async ({ file, assetType, setState, setPreview, objectUrlRef }) => {
    if (!file || !detail) return;
    if (objectUrlRef.current) URL.revokeObjectURL(objectUrlRef.current);
    const previewUrl = URL.createObjectURL(file);
    objectUrlRef.current = previewUrl;
    setPreview(previewUrl);

    try {
      let durationSeconds;
      if (assetType === "cover-video") {
        setState({ status: "checking", error: null, pct: 0 });
        durationSeconds = await new Promise((resolve, reject) => {
          const video = document.createElement("video");
          video.preload = "metadata";
          video.onloadedmetadata = () => resolve(video.duration);
          video.onerror = () => reject(new Error("Could not read this cover video"));
          video.src = previewUrl;
        });
        if (!Number.isFinite(durationSeconds) || durationSeconds <= 0 || durationSeconds > 420.5) {
          throw new Error("Cover video must be 7 minutes or shorter");
        }
      }
      setState({ status: "uploading", error: null, pct: 0 });
      // 1-2. Presign + XHR PUT to R2, with progress tracking
      const { key } = await uploadAssetToR2({
        releaseType: detail.release.release_type,
        slug:        detail.release.slug,
        assetType,
        file,
        onProgress:  (pct) => setState((s) => ({ ...s, pct })),
      });

      // 3. Complete — writes to DB; server-side revalidatePath fires automatically
      const completeRes  = await fetch("/api/admin/upload/complete", {
        method:  "POST",
        headers: { "Content-Type": "application/json" },
        body:    JSON.stringify({
          releaseId:   relStub.id,
          key,
          assetType,
          releaseType: detail.release.release_type,
          slug:        detail.release.slug,
          durationSeconds,
        }),
      });
      const completeData = await completeRes.json();
      if (!completeRes.ok) throw new Error(completeData.error || "Upload complete failed");

      setState({ status: "done", error: null, pct: 100 });
      signalCatalogMutation(`${assetType}_updated`);
      showMsg(`${assetType === "cover" ? "Cover" : "Cover video"} updated — live on storefront`);
      onSaved();
    } catch (err) {
      setPreview(null);
      setState({ status: "error", error: err.message, pct: 0 });
    }
  }, [detail, relStub, showMsg, onSaved]);

  const pickFile = (accept, handler) => {
    const inp = document.createElement("input");
    inp.type = "file";
    inp.accept = accept;
    inp.style.display = "none";
    inp.onchange = (event) => {
      const file = event.target.files?.[0];
      inp.remove();
      if (file) handler(file);
    };
    document.body.appendChild(inp);
    inp.click();
  };

  // ── Audio replace ─────────────────────────────────────────────────────────────
  const startAudioReplace = (track) => {
    setAudioReplacing(track);
    setAudioPhase("idle");
    setAudioNewKey(null);
    setAudioError("");
    setAudioProgress(0);
  };

  // A large master upload can easily outlast the 15-minute MFA-recency window
  // sensitive admin mutations require, even though the broader 12h admin
  // session is still valid. On that specific, recoverable denial, show the
  // same re-verification overlay /api/admin/releases already uses instead of
  // a dead-end "Unauthorized" — and resume exactly where the operation left
  // off (never re-upload a file that already landed in staging).
  const commitStagedMaster = useCallback(async (operation, staged) => {
    try {
      const status = await beginMasterReplacement({
        releaseId: relStub.id,
        trackId: operation.trackId,
        replacementId: staged.replacementId,
        key: staged.key,
        size: staged.size,
      });
      if (audioOperationRef.current !== operation) return;

      if (status.status === "active") {
        setAudioPhase("done");
        signalCatalogMutation("release_master_promoted");
        showMsg("New master is live");
        onSaved();
        audioOperationRef.current = null;
      } else {
        setAudioError(status.error || "Replacement failed; the previous master remains live");
        setAudioPhase("error");
        audioOperationRef.current = null;
      }
    } catch (err) {
      if (audioOperationRef.current !== operation) return;
      if (RECOVERABLE_ADMIN_AUTH_CODES.has(err.data?.code)) {
        audioResumeRef.current = () => commitStagedMaster(operation, staged);
        setAudioReauthRequired(true);
        return;
      }
      setAudioError(err.message);
      setAudioPhase("error");
      audioOperationRef.current = null;
    }
  }, [relStub, showMsg, onSaved]);

  const uploadAudio = useCallback(async (file) => {
    if (!file || !audioReplacing || !detail) return;
    const operation = {
      file,
      trackId: audioReplacing.id,
      releaseId: relStub.id,
      replacementId: null,
    };
    audioOperationRef.current = operation;
    setAudioPhase("uploading");
    setAudioProgress(0);

    let staged;
    try {
      staged = await stageMasterReplacement({
        releaseId: relStub.id,
        trackId: audioReplacing.id,
        file,
        onProgress: setAudioProgress,
        xhrRef: audioXhrRef,
      });
    } catch (err) {
      if (audioOperationRef.current !== operation) return;
      if (RECOVERABLE_ADMIN_AUTH_CODES.has(err.data?.code)) {
        audioResumeRef.current = () => uploadAudio(file);
        setAudioReauthRequired(true);
        return;
      }
      setAudioError(err.message);
      setAudioPhase("error");
      audioOperationRef.current = null;
      return;
    }
    if (audioOperationRef.current !== operation) return;
    operation.replacementId = staged.replacementId;
    setAudioNewKey(staged.key);
    setAudioPhase("processing");

    await commitStagedMaster(operation, staged);
  }, [audioReplacing, detail, relStub, commitStagedMaster]);

  const cancelAudioReplace = () => {
    audioOperationRef.current = null;
    audioResumeRef.current = null;
    setAudioReauthRequired(false);
    setAudioReplacing(null);
    setAudioPhase("idle");
  };

  const removeTrackFromRelease = async () => {
    if (!removeCandidate || removingTrackId) return;
    const target = removeCandidate;
    setRemovingTrackId(target.id);
    setRemoveTrackError("");
    try {
      const response = await fetch(`/api/admin/releases/${relStub.id}/tracks/${target.id}`, { method: "DELETE" });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || "Track removal failed");
      setDetail((current) => current ? {
        ...current,
        tracks: current.tracks.filter((track) => track.id !== target.id)
          .map((track, index) => ({ ...track, position: index + 1 })),
      } : current);
      setTrackLyrics((current) => {
        const next = { ...current };
        delete next[target.id];
        return next;
      });
      setRemoveCandidate(null);
      setSwipedTrackId(null);
      signalCatalogMutation("release_track_removed");
      showMsg("Track removed from this release. Its audio master and rights history were preserved.");
      onSaved();
    } catch (error) {
      setRemoveTrackError(error.message || "Track removal failed");
    } finally {
      setRemovingTrackId(null);
    }
  };

  const handleTrackTouchStart = (event, trackId) => {
    const touch = event.touches?.[0];
    if (touch) trackTouchStartRef.current = { x: touch.clientX, y: touch.clientY, trackId };
  };
  const handleTrackTouchEnd = (event, trackId) => {
    const start = trackTouchStartRef.current;
    trackTouchStartRef.current = null;
    const touch = event.changedTouches?.[0];
    if (!start || !touch || start.trackId !== trackId) return;
    const dx = touch.clientX - start.x;
    const dy = touch.clientY - start.y;
    if (Math.abs(dx) < 56 || Math.abs(dx) < Math.abs(dy) * 1.25) return;
    setSwipedTrackId(dx < 0 ? trackId : null);
  };

  // ── Render ────────────────────────────────────────────────────────────────────
  if (loading) {
    return (
      <div style={{ padding: "60px 0", textAlign: "center", color: C.muted, fontFamily: "-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif" }}>
        Loading release…
      </div>
    );
  }

  if (loadError || !detail) {
    return (
      <div style={{ padding: "40px 0", fontFamily: "-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif" }}>
        <button onClick={onBack} style={backBtnStyle}>← My Releases</button>
        <div style={{ color: C.error, fontSize: 13, marginTop: 16 }}>{loadError || "Failed to load release"}</div>
      </div>
    );
  }

  const lyricRecordings = detail.lyric_recordings || detail.tracks;
  const lyricTrack = lyricRecordings.find(track => track.id === lyricRecordingId) || lyricRecordings[0];

  const sectionDefs = [
    { id: "metadata", label: "Info" },
    { id: "credits",  label: "Credits & IDs" },
    { id: "cover",    label: "Cover Art" },
    { id: "audio",    label: "Audio" },
    { id: "lyrics",   label: "Lyrics" },
  ];

  return (
    <div style={{ padding: "28px 0 80px", fontFamily: "-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif" }}>
      {/* Header with inline cover art thumbnail */}
      <div style={{ marginBottom: 22 }}>
        <button onClick={onBack} style={backBtnStyle}>← My Releases</button>
        <div style={{ display: "flex", alignItems: "center", gap: 14, marginTop: 10, flexWrap: "wrap" }}>
          <div style={{
            width: 60, height: 60, borderRadius: 10, overflow: "hidden", flexShrink: 0,
            background: C.surface2, border: `1px solid ${C.border}`,
            display: "flex", alignItems: "center", justifyContent: "center",
          }}>
            {coverPreview
              ? <img src={coverPreview} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              : <span style={{ fontSize: 24 }}>🎵</span>
            }
          </div>
          <div>
            <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
              <h2 style={{ fontSize: 20, fontWeight: 900, color: C.text, margin: 0 }}>
                {detail.product?.title || detail.release.slug}
              </h2>
              <StatusBadge status={detail.release.status} />
              <span style={{ fontSize: 11, color: C.muted2 }}>{TYPE_LABELS[detail.release.release_type]}</span>
            </div>
            <div style={{ fontSize: 11, color: C.muted3, marginTop: 3 }}>/{detail.release.slug}</div>
          </div>
        </div>
      </div>

      {/* Section tabs */}
      <div style={{ display: "flex", gap: 6, marginBottom: 20, flexWrap: "wrap" }}>
        {sectionDefs.map(({ id, label }) => (
          <button
            key={id}
            onClick={() => setSection(id)}
            style={{
              background: section === id ? C.accentDim : C.surface2,
              border: `1px solid ${section === id ? C.accentBorder : C.border}`,
              borderRadius: 7, padding: "8px 16px", fontSize: 12, fontWeight: 700,
              color: section === id ? C.accent : C.muted, cursor: "pointer",
              fontFamily: "inherit", letterSpacing: "0.05em",
            }}
          >
            {label}
          </button>
        ))}
      </div>

      <SaveMsg msg={saveMsg} />

      <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 14, padding: "28px" }}>

        {/* ── INFO ── */}
        {section === "metadata" && (
          <div>
            <h3 style={{ fontSize: 15, fontWeight: 900, color: C.text, marginBottom: 20, marginTop: 0 }}>Release Info</h3>
            <Field label="Title">
              <Inp value={editTitle} onChange={setEditTitle} placeholder="Release title" />
            </Field>
            <Field label="Artist"><Inp value={editArtist} onChange={setEditArtist} /></Field>
            <Field label="Release Type"><Sel value={editType} onChange={setEditType}>{Object.entries(TYPE_LABELS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Sel></Field>
            <Field label="UPC / EAN (optional)"><Inp value={editUpc} onChange={setEditUpc} /></Field>
            <Field label="Price (USD)">
              <PriceSelector
                releaseType={detail?.release?.release_type}
                value={editPrice}
                onChange={setEditPrice}
              />
            </Field>
            <Field label="Genre">
              <Sel value={editGenre} onChange={setEditGenre}>
                <option value="">Select…</option>
                {GENRES.map((g) => <option key={g} value={g}>{g}</option>)}
              </Sel>
            </Field>
            <Field label="Original Release Date">
              <Inp type="date" value={editDate} onChange={setEditDate} />
            </Field>
            <details><summary>Publication and scheduling</summary>
              {["scheduled_at", "available_at", "release_timezone", "preorder_starts_at", "early_access_starts_at", "unavailable_at"].map(key => <Field key={key} label={key.replaceAll("_", " ")}><Inp value={editLifecycle[key] || ""} onChange={value => setEditLifecycle(p => ({ ...p, [key]: value || null }))} placeholder={key === "release_timezone" ? "America/Chicago" : "ISO date and time"} /></Field>)}
              {["upcoming_visible", "preview_before_release", "preorder_enabled", "early_access_enabled"].map(key => <label key={key} style={{ display: "block", marginBottom: 10 }}><input type="checkbox" checked={!!editLifecycle[key]} onChange={e => setEditLifecycle(p => ({ ...p, [key]: e.target.checked }))} />{key.replaceAll("_", " ")}</label>)}
              <Field label="Preorder price (cents)"><Inp value={editLifecycle.preorder_price_cents ?? ""} onChange={value => setEditLifecycle(p => ({ ...p, preorder_price_cents: value === "" ? null : Number(value) }))} /></Field>
            </details>
            <Btn onClick={saveMetadata} disabled={saving}>{saving ? "Saving…" : "Save Changes"}</Btn>
          </div>
        )}

        {section === "credits" ? <div>
          <h3>Release-level attribution</h3>
          <CreditsEditor groups={creditGroups} onChange={setCreditGroups} directoryAvailable={detail.capabilities?.ready} />
          <Field label="UPC / EAN (optional)"><Inp value={editUpc} onChange={setEditUpc} /></Field>
          {recordings.map(track => <details key={track.id} style={{ marginBottom: 20 }}><summary>{track.title || "Recording"}</summary>
            <Field label="Recording title"><Inp value={track.title || ""} onChange={title => setRecordings(rows => rows.map(t => t.id === track.id ? { ...t, title } : t))} /></Field>
            <Field label="ISRC (optional)"><Inp value={track.isrc || ""} onChange={isrc => setRecordings(rows => rows.map(t => t.id === track.id ? { ...t, isrc } : t))} /></Field>
            <label><input type="checkbox" checked={!!track.inherit_credits} onChange={e => setRecordings(rows => rows.map(t => t.id === track.id ? { ...t, inherit_credits: e.target.checked } : t))} />Use release defaults for this recording</label>
            <CreditsEditor groups={track.inherit_credits ? creditGroups : track.credit_groups} directoryAvailable={detail.capabilities?.ready} disabled={track.inherit_credits} onChange={credit_groups => setRecordings(rows => rows.map(t => t.id === track.id ? { ...t, credit_groups } : t))} />
          </details>)}
          <Btn onClick={saveCredits} disabled={saving}>{saving ? "Saving…" : "Save Credits and Identifiers"}</Btn>
        </div> : null}
        {/* ── COVER ART ── */}
        {section === "cover" && (
          <div>
            <h3 style={{ fontSize: 15, fontWeight: 900, color: C.text, marginBottom: 6, marginTop: 0 }}>Cover Art</h3>
            <p style={{ fontSize: 13, color: C.muted, marginBottom: 26 }}>
              Changes propagate to every page, every carousel, and every player immediately on save.
            </p>

            {/* Static cover */}
            <div style={{ marginBottom: 32 }}>
              <Label>Static Cover · JPEG / PNG / WEBP</Label>
              <div style={{ display: "flex", gap: 18, alignItems: "flex-start", flexWrap: "wrap" }}>
                <div
                  onClick={coverState.status !== "uploading" ? () => pickFile("image/jpeg,image/png,image/webp,.jpg,.jpeg,.png,.webp", (file) => uploadAsset({ file, assetType: "cover", setState: setCoverState, setPreview: setCoverPreview, objectUrlRef: coverPreviewObjectUrlRef })) : undefined}
                  style={{
                    width: 120, height: 120, flexShrink: 0, borderRadius: 12,
                    background: C.surface2,
                    border: `2px dashed ${coverState.status === "done" ? C.success : coverState.status === "error" ? C.error : C.border2}`,
                    cursor: coverState.status !== "uploading" ? "pointer" : "default",
                    overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center",
                  }}
                >
                  {coverPreview
                    ? <img src={coverPreview} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                    : <div style={{ textAlign: "center", padding: 12 }}>
                        <div style={{ fontSize: 28, marginBottom: 6 }}>🖼</div>
                        <div style={{ fontSize: 10, color: C.muted }}>
                          {coverState.status === "uploading" ? `${coverState.pct}%` : "Tap to upload"}
                        </div>
                      </div>
                  }
                </div>
                <div>
                  <Btn
                    variant="secondary" small
                    disabled={coverState.status === "uploading"}
                    onClick={() => pickFile("image/jpeg,image/png,image/webp,.jpg,.jpeg,.png,.webp", (file) => uploadAsset({ file, assetType: "cover", setState: setCoverState, setPreview: setCoverPreview, objectUrlRef: coverPreviewObjectUrlRef }))}
                  >
                    {coverState.status === "uploading" ? `Uploading ${coverState.pct}%…` : coverState.status === "done" ? "✓ Replace Again" : "Choose Image"}
                  </Btn>
                  {coverState.status === "uploading" && <ProgressBar pct={coverState.pct} />}
                  {coverState.status === "error" && <div style={{ fontSize: 11, color: C.error, marginTop: 6 }}>{coverState.error}</div>}
                  {coverState.status === "done" && <div style={{ fontSize: 11, color: C.success, marginTop: 6 }}>Updated on all surfaces</div>}
                  <div style={{ fontSize: 11, color: C.muted2, marginTop: 8 }}>Square recommended · Max 20 MB</div>
                </div>
              </div>
            </div>

            {/* Animated cover video */}
            <div>
              <Label>Cover Video · MP4 / MOV / WebM</Label>
              <p style={{ fontSize: 12, color: C.muted, marginBottom: 14 }}>
                Shown in the catalog grid, carousels, and immersive player on motion-enabled surfaces. Stored as a short silent loop (max 500 MB).
              </p>
              <div style={{ display: "flex", gap: 18, alignItems: "flex-start", flexWrap: "wrap" }}>
                <div style={{
                  width: 120, height: 120, flexShrink: 0, borderRadius: 12,
                  background: C.surface2,
                  border: `2px dashed ${mp4State.status === "done" ? C.success : mp4State.status === "error" ? C.error : C.border2}`,
                  overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  {mp4Preview
                    ? <video src={mp4Preview} autoPlay loop muted playsInline style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                    : <div style={{ textAlign: "center", padding: 12 }}>
                        <div style={{ fontSize: 28, marginBottom: 6 }}>🎬</div>
                        <div style={{ fontSize: 10, color: C.muted }}>
                          {mp4State.status === "uploading" ? `${mp4State.pct}%` : "No animated cover"}
                        </div>
                      </div>
                  }
                </div>
                <div>
                  <Btn
                    variant="secondary" small
                    disabled={mp4State.status === "checking" || mp4State.status === "uploading"}
                    onClick={() => pickFile(VIDEO_COVER_ACCEPT, (file) => uploadAsset({ file, assetType: "cover-video", setState: setMp4State, setPreview: setMp4Preview, objectUrlRef: mp4PreviewObjectUrlRef }))}
                  >
                    {mp4State.status === "checking" ? "Checking duration…" : mp4State.status === "uploading" ? `Uploading ${mp4State.pct}%…` : mp4State.status === "done" ? "✓ Replace Video" : "Upload Cover Video"}
                  </Btn>
                  {mp4State.status === "uploading" && <ProgressBar pct={mp4State.pct} />}
                  {mp4State.status === "error" && <div style={{ fontSize: 11, color: C.error, marginTop: 6 }}>{mp4State.error}</div>}
                  {mp4State.status === "done" && <div style={{ fontSize: 11, color: C.success, marginTop: 6 }}>Live on motion surfaces</div>}
                  <div style={{ fontSize: 11, color: C.muted2, marginTop: 8 }}>Up to 7 minutes · Max 500 MB</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* ── AUDIO ── */}
        {section === "audio" && (
          <div>
            <h3 style={{ fontSize: 15, fontWeight: 900, color: C.text, marginBottom: 6, marginTop: 0 }}>Replace Master Audio</h3>
            <p style={{ fontSize: 13, color: C.muted, marginBottom: 20 }}>
              Upload WAV / FLAC / AIFF. The current master keeps playing while the replacement is uploaded, validated, and transcoded. It becomes authoritative only after every output is ready; the previous revision is retained for safe rollback and active sessions.
            </p>

            {detail.tracks.length === 0 && (
              <div style={{ color: C.muted2, fontSize: 13 }}>No tracks found for this release.</div>
            )}

            {detail.tracks.map((track) => (
              <div
                key={track.id}
                onTouchStart={(event) => handleTrackTouchStart(event, track.id)}
                onTouchEnd={(event) => handleTrackTouchEnd(event, track.id)}
                onTouchCancel={() => { trackTouchStartRef.current = null; }}
                style={{ position: "relative", overflow: "hidden", borderRadius: 10, marginBottom: 10, touchAction: "pan-y" }}
              >
                <button
                  type="button"
                  aria-label={`Remove ${track.title || track.slug} from ${detail.product?.title || detail.release.slug}`}
                  onClick={() => { setRemoveTrackError(""); setRemoveCandidate(track); }}
                  disabled={audioReplacing?.id === track.id || removingTrackId === track.id}
                  style={{ position: "absolute", inset: "0 0 0 auto", width: 104, border: 0, borderRadius: 10, background: "rgba(255,69,58,0.18)", color: C.error, font: "inherit", fontSize: 12, fontWeight: 800, cursor: "pointer", opacity: audioReplacing?.id === track.id ? 0.45 : 1 }}
                >Remove Track</button>
                <div style={{ position: "relative", background: C.surface2, border: `1px solid ${C.border}`, borderRadius: 10, padding: "14px 16px", transition: "transform 160ms ease", transform: swipedTrackId === track.id ? "translateX(-104px)" : "translateX(0)" }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
                  <div>
                    <div style={{ fontSize: 13, fontWeight: 700, color: C.text }}>
                      {detail.tracks.length > 1 ? `${track.position}. ` : ""}{track.title || track.slug}
                    </div>
                    <div style={{ fontSize: 11, color: track.has_audio ? C.success : C.muted2, marginTop: 2 }}>
                      {track.has_audio ? "✓ Audio on file" : "No audio yet"}
                      {track.upload_status && track.upload_status !== "ready" ? ` · ${track.upload_status}` : ""}
                    </div>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                    {audioReplacing?.id !== track.id && (
                      <button
                        onClick={() => startAudioReplace(track)}
                        style={{ background: C.surface, border: `1px solid ${C.border2}`, borderRadius: 7, padding: "7px 14px", fontSize: 11, color: C.muted, cursor: "pointer", fontFamily: "inherit", fontWeight: 700 }}
                      >
                        Replace Master
                      </button>
                    )}
                    <button
                      type="button"
                      onClick={() => { setRemoveTrackError(""); setRemoveCandidate(track); }}
                      disabled={removingTrackId === track.id || audioReplacing?.id === track.id}
                      style={{ background: "rgba(255,69,58,0.08)", border: `1px solid rgba(255,69,58,0.3)`, borderRadius: 7, padding: "7px 12px", fontSize: 11, color: C.error, cursor: "pointer", fontFamily: "inherit", fontWeight: 700 }}
                    >Remove Track</button>
                  </div>
                </div>


                {/* Inline replace flow for this track */}
                {audioReplacing?.id === track.id && (
                  <div style={{ marginTop: 12, borderTop: `1px solid ${C.border}`, paddingTop: 12 }}>
                    {audioPhase === "idle" && (
                      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                        <button
                          onClick={() => pickFile(MASTER_AUDIO_ACCEPT, uploadAudio)}
                          style={{ background: C.accent, border: "none", borderRadius: 8, padding: "9px 18px", fontSize: 12, fontWeight: 700, color: "#000", cursor: "pointer", fontFamily: "inherit" }}
                        >
                          Select New Master
                        </button>
                        <button onClick={cancelAudioReplace} style={{ background: "none", border: `1px solid ${C.border}`, borderRadius: 8, padding: "9px 14px", fontSize: 12, color: C.muted, cursor: "pointer", fontFamily: "inherit" }}>Cancel</button>
                      </div>
                    )}
                    {audioPhase === "uploading" && (
                      <div>
                        <div style={{ fontSize: 12, color: C.accent, fontWeight: 700 }}>
                          {`Uploading new master… ${audioProgress}%`}
                        </div>
                        <ProgressBar pct={audioProgress} />
                      </div>
                    )}
                    {audioPhase === "processing" && (
                      <div>
                        <div style={{ fontSize: 12, color: C.warn, fontWeight: 700 }}>Verifying and committing the new master…</div>
                        <div style={{ fontSize: 11, color: C.muted2, marginTop: 5 }}>HLS regenerates in the background afterward — playback already uses the new file.</div>
                      </div>
                    )}
                    {audioPhase === "done" && (
                      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                        <span>✅</span>
                        <span style={{ fontSize: 12, color: C.success, fontWeight: 700 }}>New master is live</span>
                        <button onClick={cancelAudioReplace} style={{ background: "none", border: "none", color: C.muted2, fontSize: 12, cursor: "pointer", fontFamily: "inherit" }}>Done</button>
                      </div>
                    )}
                    {audioPhase === "error" && (
                      <div>
                        <div style={{ fontSize: 12, color: C.error, marginBottom: 8 }}>{audioError}</div>
                        <div style={{ display: "flex", gap: 8 }}>
                          <button onClick={() => { setAudioPhase("idle"); setAudioError(""); }} style={{ background: "none", border: `1px solid ${C.border}`, borderRadius: 8, padding: "8px 14px", fontSize: 12, color: C.muted, cursor: "pointer", fontFamily: "inherit" }}>Try Again</button>
                          <button onClick={cancelAudioReplace} style={{ background: "none", border: "none", color: C.muted2, fontSize: 12, cursor: "pointer", fontFamily: "inherit" }}>Cancel</button>
                        </div>
                      </div>
                    )}
                    {audioReauthRequired && (
                      <AdminVerificationOverlay
                        email={currentUser?.email || ""}
                        onCancel={() => {
                          audioResumeRef.current = null;
                          setAudioReauthRequired(false);
                          setAudioError("Re-verification was cancelled; the previous master remains live");
                          setAudioPhase("error");
                          audioOperationRef.current = null;
                        }}
                        onVerified={() => {
                          setAudioReauthRequired(false);
                          const resume = audioResumeRef.current;
                          audioResumeRef.current = null;
                          resume?.();
                        }}
                      />
                    )}
                  </div>
                )}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* ── LYRICS ── */}
        {section === "lyrics" && (
          <div>
            <h3 style={{ fontSize: 15, fontWeight: 900, color: C.text, marginBottom: 6, marginTop: 0 }}>Lyrics</h3>
            <p style={{ fontSize: 13, color: C.muted, marginBottom: 20 }}>Edit lyric text or synchronize each line and word to the recording. Apply timings, then save.</p>

            {(detail.lyric_recordings || detail.tracks).length === 0 && (
              <div style={{ color: C.muted2, fontSize: 13 }}>No tracks found.</div>
            )}

            {lyricRecordings.length > 1 ? <div style={{ marginBottom: 18 }}>
              <label htmlFor="lyric-recording-select" style={{ color: C.muted, fontSize: 12 }}>Recording to edit</label>
              <select id="lyric-recording-select" aria-label="Lyric recording" value={lyricTrack?.id || ""} disabled={saving}
                onChange={event => setLyricRecordingId(event.target.value)}
                style={{ display: "block", width: "100%", minHeight: 48, padding: "10px 12px", marginTop: 7, background: C.surface2, color: C.text, border: `1px solid ${C.border2}`, borderRadius: 9 }}>
                {lyricRecordings.map(track => <option key={track.id} value={track.id}>{track.position}. {track.title || "Recording"} - {lyricStatus(trackLyrics[track.id] || "")}</option>)}
              </select>
              <p style={{ color: C.muted, fontSize: 12, lineHeight: 1.7, marginTop: 8 }}>Your edits stay with each recording when you switch. Save Lyrics saves the release; apply or remove any timing drafts first.</p>
            </div> : null}
            {lyricTrack ? <LyricTimingEditor
              key={lyricTrack.id} value={trackLyrics[lyricTrack.id] || ""}
              onChange={lyrics => setTrackLyrics(previous => ({ ...previous, [lyricTrack.id]: lyrics }))}
              releaseId={detail.release.id} recordingId={lyricTrack.id} title={lyricTrack.title || "Recording"} disabled={saving} coverUrl={coverPreview}
            /> : null}

            {(detail.lyric_recordings || detail.tracks).length > 0 && (
              <Btn onClick={saveLyrics} disabled={saving}>{saving ? "Saving…" : "Save Lyrics"}</Btn>
            )}
          </div>
        )}
      </div>

      {removeCandidate && (
        <div
          role="alertdialog"
          aria-modal="true"
          aria-labelledby="remove-release-track-title"
          aria-describedby="remove-release-track-description"
          style={{ position: "fixed", inset: 0, zIndex: 10000, background: "rgba(0,0,0,0.78)", display: "grid", placeItems: "center", padding: 20 }}
        >
          <div style={{ width: "min(100%, 440px)", background: C.surface, border: `1px solid ${C.border2}`, borderRadius: 14, padding: 22, boxShadow: "0 20px 70px rgba(0,0,0,0.55)" }}>
            <h3 id="remove-release-track-title" style={{ margin: "0 0 10px", color: C.text, fontSize: 17, fontWeight: 850 }}>Remove track from release?</h3>
            <p style={{ margin: "0 0 8px", color: C.text, fontSize: 14, fontWeight: 700 }}>{removeCandidate.title || removeCandidate.slug}</p>
            <p style={{ margin: "0 0 14px", color: C.muted, fontSize: 13, lineHeight: 1.55 }}>{detail.product?.title || detail.release.slug}</p>
            <p id="remove-release-track-description" style={{ margin: "0 0 16px", color: C.muted2, fontSize: 12, lineHeight: 1.55 }}>
              This removes the track from this release’s tracklist and compacts its order. The audio master, replacement history, visuals, and existing rights records are preserved.
            </p>
            {removeTrackError && <div role="alert" style={{ color: C.error, fontSize: 12, marginBottom: 14 }}>{removeTrackError}</div>}
            <div style={{ display: "flex", justifyContent: "flex-end", gap: 9, flexWrap: "wrap" }}>
              <button type="button" autoFocus disabled={Boolean(removingTrackId)} onClick={() => { setRemoveCandidate(null); setRemoveTrackError(""); }} style={{ background: "transparent", border: `1px solid ${C.border2}`, borderRadius: 8, padding: "9px 14px", color: C.muted, font: "inherit", cursor: "pointer" }}>Cancel</button>
              <button type="button" disabled={Boolean(removingTrackId)} onClick={removeTrackFromRelease} style={{ background: C.error, border: 0, borderRadius: 8, padding: "9px 14px", color: "#fff", font: "inherit", fontWeight: 800, cursor: "pointer", opacity: removingTrackId ? 0.65 : 1 }}>
                {removingTrackId ? "Removing…" : "Remove Track"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const backBtnStyle = {
  background: "none", border: "none", color: C.muted2, fontSize: 11, cursor: "pointer",
  padding: 0, fontFamily: "inherit", letterSpacing: "0.08em", fontWeight: 700, textTransform: "uppercase",
};

// ── Root component ────────────────────────────────────────────────────────────────
// View state machine: "home" ⟶ "upload" or "list" ⟶ "edit"
// Auth is gated by AuthSurfaceIsland in HomeClient; double-checked here via useAuth().
export default function InlineReleasesManager() {
  const { isAdmin, currentUser } = useAuth();

  const [view,           setView]           = useState("home"); // "home" | "upload" | "list" | "edit"
  const [releases,       setReleases]       = useState([]);
  const [releasesLoaded, setReleasesLoaded] = useState(false);
  const [loading,        setLoading]        = useState(false);
  const [loadError,      setLoadError]      = useState(null);
  const [filter,         setFilter]         = useState("all");
  const [typeFilter,     setTypeFilter]     = useState("all");
  const [editingRelease, setEditingRelease] = useState(null);
  const [deletionNotice, setDeletionNotice] = useState("");
  const [lastResult,     setLastResult]     = useState(null);
  const [reauthRequired, setReauthRequired] = useState(false);

  const loadReleases = useCallback(async () => {
    setLoading(true);
    setLoadError(null);
    try {
      const res  = await fetch("/api/admin/releases");
      const json = await res.json();
      if (!res.ok) {
        if (RECOVERABLE_ADMIN_AUTH_CODES.has(json.code)) {
          setReauthRequired(true);
          return;
        }
        throw new Error(json.error || "Failed to load releases");
      }
      const deleted = new Set(getDeletedReleaseSnapshot());
      setReleases((json.releases || []).filter((release) => !deleted.has(release.slug)));
      setReleasesLoaded(true);
      setReauthRequired(false);
    } catch (err) {
      setLoadError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  if (!isAdmin) return null;

  // ── Upload view (also handles resuming a draft — a draft is a release that
  // hasn't been published yet, and must go through the exact same full wizard
  // used to create one, never a limited metadata-only form) ──────────────────────
  if (view === "upload") {
    return (
      <UploadWizard
        initialReleaseId={editingRelease?.status === "draft" ? editingRelease.id : null}
        onComplete={(result) => {
          setLastResult(result);
          setEditingRelease(null);
          loadReleases();
          setView("list");
        }}
        onDismiss={() => { setEditingRelease(null); setView(releasesLoaded ? "list" : "home"); }}
      />
    );
  }

  // ── Edit view — published/scheduled releases only. Drafts are routed to the
  // full wizard above instead (see onEdit below). ─────────────────────────────────
  if (view === "edit" && editingRelease) {
    return (
      <ReleaseEditorPanel
        release={editingRelease}
        onBack={() => setView("list")}
        onSaved={loadReleases}
      />
    );
  }

  // ── List view ──────────────────────────────────────────────────────────────────
  if (view === "list") {
    return (
      <>
        <ReleaseListView
          onDeleted={(release) => {
            setReleases((current) => current.filter((item) => item.id !== release.id && item.slug !== release.slug));
            setDeletionNotice(`Deleted “${release.title || release.slug}”. Recordings and purchase history retained.`);
          }}
          deletionNotice={deletionNotice}
          releases={releases}
          loading={loading}
          error={loadError}
          filter={filter}
          onFilter={setFilter}
          typeFilter={typeFilter}
          onTypeFilter={setTypeFilter}
          onRefresh={loadReleases}
          onNew={() => { setEditingRelease(null); setView("upload"); }}
          onBack={() => setView("home")}
          onEdit={(rel) => { setEditingRelease(rel); setView(rel.status === "draft" ? "upload" : "edit"); }}
          lastResult={lastResult}
        />
        {reauthRequired && (
          <AdminVerificationOverlay
            email={currentUser?.email || ""}
            onCancel={() => { setReauthRequired(false); setView("home"); }}
            onVerified={loadReleases}
          />
        )}
      </>
    );
  }

  // ── Home landing ───────────────────────────────────────────────────────────────
  return (
    <HomeLanding
      releaseCount={releases.length}
      onUpload={() => setView("upload")}
      onMyReleases={() => {
        if (!releasesLoaded) loadReleases();
        setView("list");
      }}
    />
  );
}

